import{_ as r,o as d,c as e,a2 as a}from"./chunks/framework.BWuWLRhz.js";const c=JSON.parse('{"title":"支援的檔案管理器","description":"","frontmatter":{},"headers":[],"relativePath":"zh-HK/user-guide/file-manager-support.md","filePath":"zh-HK/user-guide/file-manager-support.md","lastUpdated":1787015899000}'),o={name:"zh-HK/user-guide/file-manager-support.md"};function s(n,t,i,h,l,p){return d(),e("div",null,[...t[0]||(t[0]=[a('<h1 id="支援的檔案管理器" tabindex="-1">支援的檔案管理器 <a class="header-anchor" href="#支援的檔案管理器" aria-label="Permalink to &quot;支援的檔案管理器&quot;">​</a></h1><p>Lertaro 不只是能搜尋——它還可以和你正在使用的檔案管理器或對話方塊進行集成。根據目標視窗的不同，集成最多可以提供以下三種能力：</p><ul><li><strong>內嵌搜尋</strong> —— Lertaro 的搜尋框會直接嵌入目標視窗(也就是<a href="./getting-started.html#三種視窗">內嵌視窗</a>)，不用離開它就能搜尋。</li><li><strong>快速導航</strong> —— 目標視窗會響應<a href="./hotkeys.html#快速導航-滑鼠">快速導航的滑鼠觸發方式</a>(雙擊/中鍵，或者內嵌視窗自帶的圖示)，彈出一個包含收藏夾、歷史記錄和快捷資料夾的級聯選單。</li><li><strong>活動路徑檢測</strong> —— Lertaro 能識別目標視窗當前打開的是哪個資料夾，從而把搜尋範圍限定在該資料夾內，並讓複製路徑這類基於相對路徑的動作能正確解析。</li></ul><p>並不是每種集成都同時提供這三種能力——具體見下表。</p><h2 id="快速導航中的目前開啟資料夾" tabindex="-1">快速導航中的目前開啟資料夾 <a class="header-anchor" href="#快速導航中的目前開啟資料夾" aria-label="Permalink to &quot;快速導航中的目前開啟資料夾&quot;">​</a></h2><p>在 Folder Cascader 外掛程式啟用<strong>顯示目前開啟的資料夾</strong>後(預設啟用)，快速導航會在收藏夾和歷史記錄之前加入<strong>目前開啟的資料夾</strong>群組。它會彙整所有受支援檔案管理器目前開啟的真實檔案系統資料夾，並自動移除重複路徑。虛擬位置與已不存在的資料夾不會顯示，因此清單中的每一項都可以正常跳轉。</p><h2 id="內置-無需額外安裝" tabindex="-1">內置(無需額外安裝) <a class="header-anchor" href="#內置-無需額外安裝" aria-label="Permalink to &quot;內置(無需額外安裝)&quot;">​</a></h2><p>以下幾項都隨 Lertaro 的核心擴展插件一起提供，不需要單獨啓用。</p><table tabindex="0"><thead><tr><th>目標</th><th>內嵌搜尋</th><th>快速導航</th><th>活動路徑檢測</th></tr></thead><tbody><tr><td>Windows 檔案總管</td><td>支援</td><td>雙擊或中鍵</td><td>支援</td></tr><tr><td>現代打開/保存檔案對話方塊</td><td>支援(這個對話方塊本身就是內嵌視窗)</td><td>中鍵，或左鍵點擊內嵌視窗自帶的圖示</td><td>——</td></tr><tr><td>經典打開/保存檔案對話方塊</td><td>支援</td><td>中鍵，或左鍵點擊內嵌視窗自帶的圖示</td><td>——</td></tr><tr><td>經典瀏覽資料夾對話方塊</td><td>支援</td><td>中鍵，或左鍵點擊內嵌視窗自帶的圖示</td><td>——</td></tr></tbody></table><p>活動路徑檢測對這幾個對話方塊本身沒有意義——一旦 Lertaro 已經嵌入對話方塊裏，就不存在另一個&quot;其它視窗&quot;可供它檢測並作為搜尋範圍了。</p><h2 id="可選插件-設定-→-插件" tabindex="-1">可選插件(設定 → 插件) <a class="header-anchor" href="#可選插件-設定-→-插件" aria-label="Permalink to &quot;可選插件(設定 → 插件)&quot;">​</a></h2><p>下面每一項都是獨立的插件。在<a href="./settings/plugins.html">設定 → 插件</a>裏安裝/啓用，然後在該插件自己的<strong>配置</strong>對話方塊裏分別開關<strong>啓用內嵌搜尋</strong>和<strong>啓用快速導航</strong>——兩者預設都是開啓的。</p><table tabindex="0"><thead><tr><th>目標</th><th>內嵌搜尋</th><th>快速導航</th><th>活動路徑檢測</th></tr></thead><tbody><tr><td>Directory Opus</td><td>支援</td><td>在檔案列表區域點擊中鍵</td><td>支援</td></tr><tr><td>Files</td><td>支援</td><td>在檔案列表區域點擊中鍵</td><td>支援</td></tr><tr><td>One Commander</td><td>支援</td><td>在檔案列表區域點擊中鍵</td><td>支援</td></tr><tr><td>Total Commander</td><td>支援</td><td>在檔案列表區域點擊中鍵</td><td>支援</td></tr><tr><td>XYplorer</td><td>支援</td><td>在檔案列表區域點擊中鍵</td><td>支援</td></tr></tbody></table><p>這五款都是通過匹配運行中的處理程序來識別目標視窗的(其中 Directory Opus 和 Total Commander 還會通過它們各自公開文檔記錄的 <code>WM_COPYDATA</code> 遠程控制接口通信，而不是直接抓取介面；Files 和 One Commander 沒有提供遠程控制協議，因此改用 UI Automation)。</p><h2 id="directory-opus-的索引資料夾大小" tabindex="-1">Directory Opus 的索引資料夾大小 <a class="header-anchor" href="#directory-opus-的索引資料夾大小" aria-label="Permalink to &quot;Directory Opus 的索引資料夾大小&quot;">​</a></h2><p>啟用 Directory Opus 外掛程式中的<strong>啟用 Lertaro 大小欄</strong>選項後(預設啟用)，Lertaro 會在 Directory Opus 中安裝<strong>Lertaro 大小</strong>指令碼欄。它從 Lertaro 目前記憶體中的索引顯示每個已索引資料夾的遞迴大小，不會掃描磁碟。檔案列仍使用 Directory Opus 原生的大小欄；Lertaro 沒有索引的資料夾在此欄中不會顯示值。關閉該選項後，Lertaro 不會再寫入或更新指令碼；已經安裝的指令碼會被刻意保留。</p><p>在 Directory Opus 的欄選擇器中新增<strong>Lertaro 大小</strong>。要讓它在切換目錄和重新啟動 Directory Opus 後持續顯示，請依次選擇<strong>資料夾 → 資料夾格式 → 儲存 → 將格式儲存給所有資料夾</strong>。本機磁碟、網路磁碟機等更具體的資料夾格式優先於使用者預設格式；如有這類格式，也需要把該欄加入對應格式。</p><h2 id="應用程式自帶的對話方塊-可選插件" tabindex="-1">應用程式自帶的對話方塊(可選插件) <a class="header-anchor" href="#應用程式自帶的對話方塊-可選插件" aria-label="Permalink to &quot;應用程式自帶的對話方塊(可選插件)&quot;">​</a></h2><p>這幾項針對的是第三方應用程式裏的某一個特定對話方塊——而不是整個應用程式，跟上面內置的那幾個對話方塊是同一個思路。在<a href="./settings/plugins.html">設定 → 插件</a>裏安裝/啓用，每個插件只有一個組件，直接在那裏開關即可(沒有單獨的配置對話方塊，因為也沒有別的東西需要切換)。</p><table tabindex="0"><thead><tr><th>目標</th><th>內嵌搜尋</th><th>快速導航</th><th>活動路徑檢測</th></tr></thead><tbody><tr><td>WPS Office 的打開/儲存對話方塊</td><td>支援</td><td>中鍵，或左鍵點擊內嵌視窗自帶的圖示</td><td>——</td></tr><tr><td>WinRAR 的解壓對話方塊</td><td>支援</td><td>中鍵，或左鍵點擊內嵌視窗自帶的圖示</td><td>——</td></tr><tr><td>Bandizip 的解壓對話方塊</td><td>支援</td><td>中鍵，或左鍵點擊內嵌視窗自帶的圖示</td><td>——</td></tr><tr><td>Bandizip 的添加檔案對話方塊</td><td>支援</td><td>中鍵，或左鍵點擊內嵌視窗自帶的圖示</td><td>——</td></tr></tbody></table><p>識別靠的是控件結構而不是視窗標題，所以每款軟件不管裝的是哪種語言包都能正常工作。WPS 那一項覆蓋文字、表格、演示和 PDF——它們用的是同一個對話方塊；WPS 不使用 Windows 自帶的對話方塊，而是自繪了一個，這也正是它需要單獨一個插件、而大多數程式被上面內置的那幾項覆蓋的原因。跟內置的那幾個一樣，活動路徑檢測在這裏也沒有意義——Lertaro 已經嵌入對話方塊本身了，不存在另一個&quot;其它視窗&quot;可供它檢測並作為搜尋範圍。</p><hr><p>想為這裏沒有列出的檔案管理器開發自己的集成？參見開發手冊裏的<a href="./../dev-guide/sdk/system-adapters.html">系統與對話方塊適配</a>參考文檔。</p>',23)])])}const g=r(o,[["render",s]]);export{c as __pageData,g as default};
